// Builds the MCP poster grid (app/server/mcp/poster-grid/) into one HTML string with inline CSS and JS, and writes
// app/server/mcp/poster-grid/html.generated.ts. Run it after changing any of the grid's source files:
//   node scripts/build-mcp-poster-grid.mjs
// The generated file records a hash of its sources; a unit test fails when the two disagree.
import { createHash } from "node:crypto"
import { readFile, writeFile } from "node:fs/promises"
import { gzipSync } from "node:zlib"
import { build, transform } from "esbuild"

const dir = new URL("../app/server/mcp/poster-grid/", import.meta.url)
// The logo's G comes from the site's wordmark component, so it is a source too.
export const SOURCES = [
	"cards.ts",
	"widget.ts",
	"widget.css",
	"template.html",
	"../../../ui/brand/GoodWatchWordmark.tsx",
]

export async function sourceHash() {
	const hash = createHash("sha256")
	for (const name of SOURCES) hash.update(await readFile(new URL(name, dir)))
	return hash.digest("hex").slice(0, 16)
}

async function logoPaths() {
	const wordmark = await readFile(
		new URL("../../../ui/brand/GoodWatchWordmark.tsx", dir),
		"utf8",
	)
	const path = (name) => {
		const match = new RegExp(`const ${name} =\\s*"([^"]+)"`).exec(wordmark)
		if (!match) throw new Error(`${name} not found in GoodWatchWordmark.tsx`)
		return match[1]
	}
	return { ring: path("G_RING"), play: path("G_PLAY") }
}

export async function buildPosterGrid() {
	const script = await build({
		entryPoints: [new URL("widget.ts", dir).pathname],
		bundle: true,
		minify: true,
		format: "iife",
		target: "es2020",
		write: false,
		legalComments: "none",
	})
	const css = await transform(
		await readFile(new URL("widget.css", dir), "utf8"),
		{
			loader: "css",
			minify: true,
		},
	)
	const template = await readFile(new URL("template.html", dir), "utf8")
	const { ring, play } = await logoPaths()
	const js = script.outputFiles[0].text
		.replace("__G_RING__", () => ring)
		.replace("__G_PLAY__", () => play)
		.trim()
		.replaceAll("</script", "<\\/script")
	return template
		.replace(/>\s+</g, "><")
		.replace("/* CSS */", () =>
			css.code.trim().replaceAll("</style", "<\\/style"),
		)
		.replace("/* JS */", () => js)
		.trim()
}

if (import.meta.url === `file://${process.argv[1]}`) {
	const html = await buildPosterGrid()
	const out = `// Generated by scripts/build-mcp-poster-grid.mjs from cards.ts, widget.ts, widget.css and template.html.
// Don't edit: change the sources and run \`node scripts/build-mcp-poster-grid.mjs\`.
// __GW_ORIGIN__ stands for the site's origin; the resource fills it in when a client reads it.
export const POSTER_GRID_SOURCE_HASH = "${await sourceHash()}"
export const POSTER_GRID_TEMPLATE = ${JSON.stringify(html)}
`
	await writeFile(new URL("html.generated.ts", dir), out)
	const bytes = Buffer.byteLength(html)
	console.log(
		`Poster grid: ${bytes} bytes, ${gzipSync(html).length} bytes gzipped`,
	)
}
